/* Platform help lives outside the student's syllabus and generated content. */
(function (root) {
  'use strict';
  if (root.JornadaManuals?.version === 175) return;

  const guides = [
    {
      id: 'manual-01-ciclo-estudos',
      title: 'Manual 01 — Do Caos ao Método: Como Funciona o Ciclo de Estudos Dinâmico',
      label: 'Ciclo e rotina',
      intro: 'Um ciclo é uma fila de blocos de estudo. Ele pode ajudar quando sua semana muda: ao voltar, retome o próximo bloco que couber no tempo disponível.',
      sections: [
        { title: 'Monte uma rotina que você consiga cumprir', points: [
          'Use seu edital para escolher as disciplinas. Considere peso, dificuldade, proximidade da prova e seu histórico de respostas.',
          'Escolha a duração dos blocos conforme sua disponibilidade e concentração. Não existe uma duração ou distribuição de tempo que sirva para todos.',
          'Combine leitura, resolução e revisão conforme o conteúdo. Ajuste a proporção quando perceber que está lendo sem conseguir recuperar o que aprendeu.'
        ] },
        { title: 'Use o aplicativo como apoio', points: [
          'Em Hoje, confira a missão e o próximo bloco antes de iniciar o cronômetro.',
          'Registre o tempo efetivamente dedicado à atividade e pause nas interrupções. O tempo registrado mostra esforço, não comprova domínio.',
          'Ao retornar depois de um imprevisto, ajuste o plano possível para o dia. Um atraso não exige recomeçar todo o ciclo.'
        ] },
        { title: 'Exemplo de adaptação', text: 'Se você tem pouco tempo hoje, pode fazer uma sessão curta de questões de uma disciplina e revisar o motivo de um erro. Em outro dia, reserve mais tempo para a teoria do ponto em que encontrou dificuldade.' }
      ],
      reminder: 'Reavalie o ciclo com seu desempenho em questões variadas e com a revisão posterior. Os indicadores do aplicativo ajudam a decidir; não garantem aprovação.'
    },
    {
      id: 'manual-02-dominando-questoes',
      title: 'Manual 02 — Dominando as Questões e Engenharia Reversa das Bancas',
      label: 'Questões e gabaritos',
      intro: 'Use a prática para descobrir o que você compreendeu e o que precisa revisar. Ler a justificativa das alternativas ajuda mais do que decorar a letra da resposta.',
      sections: [
        { title: 'Confira o recorte antes de responder', points: [
          'Selecione disciplina e assunto. Verifique também banca, dificuldade e origem quando esses dados estiverem disponíveis.',
          'Questão autoral no estilo de uma banca não é uma questão oficial daquela instituição. Confira o rótulo e a fonte.',
          'Se não houver questões para o filtro escolhido, identifique a lacuna antes de ampliar o recorte. Não trate questões de outra matéria como treino do assunto selecionado.'
        ] },
        { title: 'Leia a correção com atenção', points: [
          'Identifique o conhecimento cobrado e a parte do enunciado que sustenta a resposta.',
          'Compare sua escolha com a justificativa de cada alternativa. Palavras como “sempre” e “nunca” merecem atenção, mas não tornam uma opção automaticamente errada.',
          'Uma sugestão da IA pode ajudar a investigar uma questão sem gabarito. Ela exige conferência e não equivale ao gabarito oficial.',
          'Se houver divergência, confira o caderno, a versão da prova e o gabarito da fonte. Use o reporte de problema ou a revisão disponível no item.'
        ] },
        { title: 'Compare seu próprio histórico', text: 'Observe primeira tentativa e repetições separadamente. Uma boa taxa em poucas questões, ou na repetição do mesmo item, é uma evidência limitada. Complete a prática com questões variadas do assunto.' }
      ],
      reminder: 'Não há um percentual universal de temas repetidos por banca. Use provas e fontes identificadas para estudar padrões, sem transformar estimativas em estatísticas oficiais.'
    },
    {
      id: 'manual-03-revisao-pos-edital',
      title: 'Manual 03 — Estratégia Pós-Edital e Revisão Espaçada',
      label: 'Revisão e prioridades',
      intro: 'Revisar é tentar recuperar o conhecimento e conferir o que ainda precisa de atenção. Releitura, questões e flashcards podem cumprir papéis diferentes na sua rotina.',
      sections: [
        { title: 'Escolha o que merece voltar primeiro', points: [
          'Priorize dificuldades recentes, conteúdos relevantes no edital e pontos que você não consegue explicar sem consulta.',
          'Use a fila de revisões como lembrete. Intervalos como um, sete e trinta dias são uma referência de organização, não uma regra universal de memória.',
          'No pós-edital, ajuste o plano ao prazo restante e ao peso das disciplinas. Confira a versão do edital antes de deixar algum conteúdo de fora.'
        ] },
        { title: 'Transforme o erro em uma próxima ação', points: [
          'Tente responder antes de abrir a explicação. Depois, confronte a resposta com o material e a fonte.',
          'Classifique a dificuldade que percebeu: conceito, leitura do comando, aplicação ou falta de informação. Uma hipótese automática da IA não substitui sua conferência.',
          'Se o registro antigo não tiver a questão e as alternativas completas, revise a teoria ou importe o original. Não complete de memória as opções de uma prova.'
        ] },
        { title: 'Observe retenção, não apenas conclusão', text: 'Um tópico marcado como estudado registra uma atividade. Conseguir resolver questões diferentes e retomar o raciocínio depois de um intervalo fornece outra evidência. Evite tratar uma única bateria como domínio definitivo.' }
      ],
      reminder: 'A velocidade de esquecimento varia conforme pessoa, conteúdo e forma de prática. Este guia não atribui um percentual fixo de perda de memória.'
    },
    {
      id: 'manual-04-guia-passo-a-passo',
      title: 'Manual 04 — Guia Passo a Passo de Uso da Plataforma Jornada do Caçador',
      label: 'Como usar a plataforma',
      intro: 'Comece pelo que pretende estudar agora. Os recursos de organização, prática e revisão ficam ligados ao seu portal e aos conteúdos disponíveis.',
      sections: [
        { title: 'Prepare seu portal', points: [
          'Em Menu → Biblioteca, envie o edital na categoria correspondente. Aguarde a análise confirmada e confira se disciplinas e tópicos estão corretos.',
          'Em Hoje → Planejamento, ajuste o tempo disponível e os dias de estudo. Revise a próxima atividade antes de iniciar o foco.',
          'Em Estudar, consulte os conteúdos por disciplina. Os Manuais do Caçador ficam em Menu → Manuais do Caçador, como ajuda de uso e método.'
        ] },
        { title: 'Pratique e confira', points: [
          'Em Questões, escolha disciplina, assunto e demais filtros. Observe a origem e a situação do gabarito.',
          'Ao importar uma prova, confira a versão do caderno. Se o gabarito vier depois, use a opção de anexar ou informar a chave, mantendo a fonte de referência.',
          'No treino, “Continuar depois” guarda a retomada neste aparelho. No simulado cronometrado, o relógio continua correndo enquanto você estiver fora.',
          'Retome erros e revisões para decidir o próximo conteúdo. Compare desempenho com a quantidade de questões e sua origem, sem interpretar a meta interna como aprovação oficial.'
        ] },
        { title: 'Mantenha seus dados organizados', points: [
          'Os controles e as opções de compartilhamento continuam na Biblioteca. Confira o portal ativo ao organizar seus arquivos.',
          'Use o backup de progresso para guardar ou restaurar seus dados. Um ZIP de atualização do código é aplicado à pasta do projeto, não ao importador de progresso.',
          'Ao sair da conta ou redefinir o perfil, as retomadas locais são encerradas. Confira as informações de confirmação antes de uma operação de exclusão.'
        ] }
      ],
      reminder: 'Estes guias orientam o uso do aplicativo. Eles não são disciplinas do edital, resumos de concurso, flashcards ou questões.'
    }
  ];
  for (const guide of guides) {
    guide.content_kind = 'platform_manual';
    guide.source_label = 'Guia da plataforma';
    for (const section of guide.sections) {
      if (section.points) Object.freeze(section.points);
      Object.freeze(section);
    }
    Object.freeze(guide.sections);
    Object.freeze(guide);
  }
  Object.freeze(guides);
  const knownIds = new Set(guides.map(guide => guide.id));
  const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

  function isManual(value) {
    if (!value) return false;
    if (Array.isArray(value)) return value.some(isManual);
    if (typeof value === 'object') {
      if (value.content_kind === 'platform_manual' || value.document_type === 'platform_manual') return true;
      if (knownIds.has(value.id)) return true;
      const fields = ['id', 'category', 'subject', 'title', 'source', 'source_label'];
      return fields.some(key => typeof value[key] === 'string' && isManual(value[key])) ||
        (value.content && value.content !== value && typeof value.content === 'object' &&
          fields.some(key => typeof value.content[key] === 'string' && isManual(value.content[key]))) || false;
    }
    if (typeof value !== 'string') return false;
    const text = normalize(value).trim();
    return knownIds.has(text) || /\b(?:manuais|manual(?: oficial)?) do cacador\b/.test(text);
  }

  let returnFocus = null;
  const doc = root.document;
  const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

  function renderGuide(dialog, requestedId, focusContent = false) {
    const guide = guides.find(item => item.id === requestedId) || guides[0];
    const content = dialog.querySelector('#hunterManualsContent');
    content.innerHTML = `<p class="hmSource">${escapeHtml(guide.source_label)}</p><h3 id="hunterManualsGuideTitle" tabindex="-1">${escapeHtml(guide.title)}</h3><p class="hmIntro">${escapeHtml(guide.intro)}</p>${guide.sections.map(section => `<section class="hmSection"><h4>${escapeHtml(section.title)}</h4>${section.points ? `<ul>${section.points.map(point => `<li>${escapeHtml(point)}</li>`).join('')}</ul>` : `<p>${escapeHtml(section.text)}</p>`}</section>`).join('')}<aside class="hmReminder"><strong>Para lembrar</strong><p>${escapeHtml(guide.reminder)}</p></aside>`;
    dialog.querySelectorAll('[data-hunter-manual-id]').forEach(button => {
      const selected = button.dataset.hunterManualId === guide.id;
      button.classList.toggle('isActive', selected);
      if (selected) button.setAttribute('aria-current', 'page');
      else button.removeAttribute('aria-current');
    });
    if (focusContent) content.querySelector('h3')?.focus({preventScroll:true});
    content.scrollTop = 0;
    return guide;
  }

  function ensureDialog() {
    if (!doc?.body) return null;
    let dialog = doc.getElementById('hunterManualsDialog');
    if (dialog) return dialog;
    dialog = doc.createElement('dialog');
    dialog.id = 'hunterManualsDialog';
    dialog.className = 'hunterManualsDialog';
    dialog.setAttribute('aria-labelledby', 'hunterManualsTitle');
    dialog.setAttribute('aria-describedby', 'hunterManualsIntro');
    dialog.innerHTML = `<div class="hmHeader"><div><p class="hmEyebrow">AJUDA E MÉTODO</p><h2 id="hunterManualsTitle">Manuais do Caçador</h2></div><button type="button" class="ghost hmClose" id="closeHunterManualsBtn" aria-label="Fechar Manuais do Caçador">Fechar</button></div><p class="hmDescription" id="hunterManualsIntro">Guias para organizar sua rotina e usar o aplicativo. O conteúdo do seu edital continua em Estudar.</p><div class="hmLayout"><nav class="hmNavigation" aria-label="Guias disponíveis">${guides.map((guide,index) => `<button type="button" data-hunter-manual-id="${guide.id}" aria-controls="hunterManualsContent"><span class="hmGuideNumber" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><span>${escapeHtml(guide.label)}</span></button>`).join('')}</nav><article class="hmContent" id="hunterManualsContent" aria-labelledby="hunterManualsGuideTitle"></article></div>`;
    doc.body.appendChild(dialog);
    dialog.querySelector('#closeHunterManualsBtn').onclick = () => dialog.close();
    dialog.querySelectorAll('[data-hunter-manual-id]').forEach(button => {
      button.onclick = () => renderGuide(dialog, button.dataset.hunterManualId, true);
    });
    dialog.addEventListener('close', () => {
      const target = returnFocus?.isConnected && !returnFocus.closest?.('dialog:not([open])') ? returnFocus : doc.getElementById('moreBtn');
      target?.focus?.({preventScroll:true});
      returnFocus = null;
    });
    return dialog;
  }

  function open(requestedId) {
    const dialog = ensureDialog();
    if (!dialog) return false;
    if (!dialog.open) returnFocus = doc.activeElement;
    const menu = doc.getElementById('moreDialog');
    if (menu?.open) menu.close();
    renderGuide(dialog, typeof requestedId === 'string' ? requestedId : undefined);
    if (!dialog.open) dialog.showModal();
    dialog.querySelector('#hunterManualsGuideTitle')?.focus({preventScroll:true});
    return true;
  }

  function install() {
    if (!doc || doc.getElementById('openHunterManualsBtn')) return;
    const menu = doc.querySelector('#moreDialog .menuGrid');
    if (!menu) return;
    const button = doc.createElement('button');
    button.type = 'button';
    button.id = 'openHunterManualsBtn';
    button.className = 'menuItem';
    button.setAttribute('aria-haspopup', 'dialog');
    button.setAttribute('aria-controls', 'hunterManualsDialog');
    button.innerHTML = '<span aria-hidden="true">▱</span><span>Manuais do Caçador<small>Ajuda e método</small></span>';
    button.onclick = () => open();
    menu.appendChild(button);
  }

  root.JornadaManuals = Object.freeze({version:175, items:guides, isManual, open, install});
  root.openHunterManuals = open;
  install();
  doc?.addEventListener('DOMContentLoaded', install, {once:true});
})(typeof window === 'undefined' ? globalThis : window);
